DEF Script_Animation1 Script {
  initializeOnly SFNode tproc USE Animation1
  initializeOnly SFBool state FALSE
  initializeOnly SFTime pause 0
  inputOnly      SFTime startAt0
  outputOnly     SFTime triggerStart
  outputOnly     SFTime triggerStop
  outputOnly     SFTime triggerStartInt
  inputOnly      SFBool activated
  inputOnly      SFTime cycle

  url "vrmlscript:
 function activated( active, curtime ) {
  if( active ) {
   triggerStart = curtime;
   state = TRUE;
  }
  else {
   triggerStop = curtime;
   state = FALSE;
  }
 }
 function cycle( curtime ) {
  triggerStartInt = curtime;
 }
 function startAt0( stime ) {
  state = TRUE;
  tproc.set_startTime = stime;
  tproc.enabled = TRUE;
  pause = 0;
 }
 "
  directOutput TRUE
}

DEF Script_Sound1 Script {
  initializeOnly SFNode snd USE AClip_Sound1
  initializeOnly SFBool state FALSE
  initializeOnly SFTime pause 0
  inputOnly      SFTime toggle

  url "vrmlscript:
 function toggle( stime ) {
 if( state )
 {
  state = FALSE;
  pause = stime - snd.startTime_changed;
  snd.set_startTime = -1;
  snd.set_stopTime = stime;
 }
 else
 {
  state = TRUE;
  snd.set_startTime = stime - pause;
  snd.set_stopTime = 0;
 }
}
"
  directOutput TRUE
}

